# Sumzy - Hourly Telegram Link Checker
# Runs every hour at minute 55 to capture new YouTube links from Telegram

param(
    [string]$TelegramToken = "YOUR_TELEGRAM_BOT_TOKEN",
    [int]$CheckIntervalMs = 60000,  # Check every minute
    [int]$MaxLinksPerRun = 10,
    [string]$OutputDir = "D:\AI_PROJECTS\projects\sumzy\docs"
)

# Paths
$CachePath = "D:\AI_PROJECTS\projects\sumzy\cache"
$DocsBase = "D:\AI_PROJECTS\projects\sumzy\docs"
$IndexFile = Join-Path $OutputDir "index.html"

Write-Host "========================================" -ForegroundColor Cyan
Write-Host "  Sumzy Telegram Link Checker Started    " -ForegroundColor Cyan
Write-Host "  Time: $(Get-Date -UFormat '%Y-%m-%d %H:%M UTC')" -ForegroundColor Yellow
Write-Host "========================================" -ForegroundColor Cyan

# Get Telegram chats list (or use a saved chat ID)
function Get-TelegramChat {
    # Try to get the main channel/chat ID from config
    $ConfigPath = Join-Path $OutputDir ".telegram-chat-id.txt"
    if (Test-Path $ConfigPath) {
        return Get-Content $ConfigPath -Raw.Trim()
    }
    # Default: ask user or use a placeholder
    Write-Host "  Note: No Telegram chat ID configured. Set .telegram-chat-id.txt" -ForegroundColor Yellow
    return ""
}

# Initialize directories
$OutputDir | New-Item -ItemType Directory -Force
$CachePath | New-Item -ItemType Directory -Force

# Process a single link
function Process-Link {
    param([string]$url)

    if ($null -eq $url -or [string]::IsNullOrEmpty($url)) {
        Write-Host "  ⚠️ Empty URL skipped" -ForegroundColor Gray
        return
    }

    # Extract video ID
    $videoId = ([regex]::Match($url, '(?:v=|/)([0-9A-Za-z_-]{11}).*')).Groups[1].Value
    if ($null -eq $videoId) {
        Write-Host "  ⚠️ Could not extract video ID from: $url" -ForegroundColor Gray
        return
    }

    # Check cache first (24h retention)
    $CacheFile = Join-Path $CachePath "${videoId}.json"
    if (Test-Path $CacheFile) {
        $CachedData = Get-Content $CacheFile -Raw
        Write-Host "  ♻️ Cached data found for: $videoId" -ForegroundColor Green
        # Update timestamp in cache
        $cachedJson = $cachedData | ConvertFrom-Json
        $cachedJson.lastProcessed = (Get-Date -Format 'o')
        $cachedJson.url = $url
        $cachedJson | ConvertTo-Json | Set-Content $CacheFile -NoNewline
    } else {
        Write-Host "  🔍 NEW link processed: $videoId" -ForegroundColor Cyan

        # Use summarize skill to analyze the link
        try {
            $summary = & D:\AI_PROJECTS\projects\sumzy\utils\content-summarizer.ps1 `$url
            if ($null -eq $summary) {
                Write-Host "  ⚠️ Summarize returned null" -ForegroundColor Gray
                return
            }
        } catch {
            Write-Host "  ❌ Error summarizing: $_" -ForegroundColor Red
            return
        }
    }

    # Save processed data with timestamp
    $processedData = @{
        url = $url
        videoId = $videoId
        processedAt = (Get-Date -Format 'o')
        summary = $summary
    }

    $resultFile = Join-Path $DocsBase "${videoId}_brief.md"
    $processedData | Add-Member MemberNoteProperty "url" "$url"
    $processedData | Add-Member MemberNoteProperty "videoId" "$videoId"
    $processedData | Add-Member MemberNoteProperty "processedAt" (Get-Date -Format 'o')
    $processedData | ConvertTo-Json -Depth 10 | Set-Content $resultFile -NoNewline
}

# Main loop
Write-Host "Starting hourly check cycle..." -ForegroundColor Cyan
for ($i = 0; $i -lt $MaxLinksPerRun; $i++) {
    Start-Sleep -Milliseconds $CheckIntervalMs

    # Get Telegram links (placeholder logic)
    $ChatId = Get-TelegramChat
    if ([string]::IsNullOrEmpty($ChatId)) {
        Write-Host "  ⚠️ No chat ID available. Set .telegram-chat-id.txt" -ForegroundColor Yellow
        continue
    }

    # TODO: Integrate with actual Telegram API or use webhook handler
    $NewLinks = @()

    foreach ($link in $NewLinks) {
        Process-Link $link
    }
}

Write-Host "========================================" -ForegroundColor Cyan
Write-Host "  Check cycle complete!                " -ForegroundColor Green
Write-Host "========================================" -ForegroundColor Cyan

# Sumzy - Telegram Link Catcher & Queue Manager
# Monitors Telegram for YouTube links and queues them for processing

param(
    [string]$TelegramBotToken = "YOUR_TELEGRAM_BOT_TOKEN",
    [string]$ChatId = ""
)

# Configuration
$QueuePath = "D:\AI_PROJECTS\projects\sumzy\queue"
$ProcessedDir = "D:\AI_PROJECTS\projects\sumzy\processed"
$CacheDir = "D:\AI_PROJECTS\projects\sumzy\cache"

# Initialize directories
@($QueuePath, $ProcessedDir, $CacheDir) | ForEach-Object {
    New-Item -ItemType Directory -Force -Path $_
}

# Get chat ID from config or file
function Get-ChatId {
    if ([string]::IsNullOrEmpty($ChatId)) {
        $ConfigFile = Join-Path "D:\AI_PROJECTS\projects\sumzy" ".telegram-chat-id.txt"
        if (Test-Path $ConfigFile) {
            return Get-Content $ConfigFile -Raw.Trim()
        }
    }
    return $ChatId
}

# Check for new links in Telegram messages
function Get-NewLinks {
    param(
        [string]$BotToken,
        [string]$ChatId
    )

    # Placeholder: In real implementation, you'd use Telegram Bot API
    # For now, this simulates checking the chat

    # TODO: Implement actual Telegram API integration here
    # Using Python telegram-link-catcher.py for robust link detection
    $PythonScript = Join-Path "D:\AI_PROJECTS\projects\sumzy" "telegram\link-catcher.py"
    if (Test-Path $PythonScript) {
        & python $PythonScript --chat-id $ChatId --output $QueuePath 2>&1 | Out-Null
    }

    # Return any links found from queue
    Get-ChildItem -Path $QueuePath -Filter "*.link" | ForEach-Object {
        $_.Name.Replace(".link", "")
    }
}

# Process queued links
function Process-QueuedLinks {
    param(
        [int]$MaxToProcess = 10
    )

    $Links = Get-NewLinks -BotToken $TelegramBotToken -ChatId (Get-ChatId)

    foreach ($link in $Links) {
        if ([string]::IsNullOrEmpty($link)) { continue }

        Write-Host "  Found link: $link" -ForegroundColor Cyan
        Process-SingleLink $link
    }
}

# Process a single link
function Process-SingleLink {
    param([string]$url)

    # Extract video ID
    if ($match = [regex]::Match($url, '(?:v=|/)([0-9A-Za-z_-]{11}).*')) {
        $videoId = $match.Groups[1].Value
    } else {
        Write-Host "  ⚠️ Could not extract video ID" -ForegroundColor Yellow
        return
    }

    # Check if already processed (24h retention)
    $CacheFile = Join-Path $CacheDir "${videoId}.json"
    if (Test-Path $CacheFile) {
        $CachedData = Get-Content $CacheFile -Raw | ConvertFrom-Json
        Write-Host "  ♻️ Cached data found for: $videoId" -ForegroundColor Green
        Update-CacheTimestamp $CacheFile
        return
    }

    # Use summarize skill to analyze the link
    try {
        $Summary = & D:\AI_PROJECTS\projects\sumzy\utils\content-summarizer.ps1 `$url
        if ($null -eq $Summary) { return }
    } catch {
        Write-Host "  ❌ Error summarizing: $_" -ForegroundColor Red
        return
    }

    # Save processed data
    $ProcessedData = @{
        url = $url
        videoId = $videoId
        processedAt = Get-Date -Format 'o'
        summary = $Summary
        category = "📹 YouTube"
    }

    $ResultFile = Join-Path $ProcessedDir "${videoId}_brief.md"
    $ProcessedData | ConvertTo-Json -Depth 10 | Set-Content $ResultFile -NoNewline

    # Update cache with processed info
    Update-CacheWithSummary -CacheFile $CacheFile -Summary $Summary
}

# Update cache timestamp
function Update-CacheTimestamp {
    param([string]$CacheFile)

    if (Test-Path $CacheFile) {
        $CachedData = Get-Content $CacheFile -Raw | ConvertFrom-Json
        $CachedData.lastProcessed = Get-Date -Format 'o'
        $CachedData.url = (Get-Content $CacheFile -Raw)
        $CachedData | ConvertTo-Json | Set-Content $CacheFile -NoNewline
    }
}

# Update cache with summary data
function Update-CacheWithSummary {
    param(
        [string]$CacheFile,
        [string]$Summary
    )

    if (Test-Path $CacheFile) {
        $CachedData = Get-Content $CacheFile -Raw | ConvertFrom-Json
        $CachedData.summary = $Summary
        $CachedData.processedAt = Get-Date -Format 'o'
        $CachedData | ConvertTo-Json | Set-Content $CacheFile -NoNewline
    }
}

# Main execution
Write-Host "========================================" -ForegroundColor Cyan
Write-Host "  Sumzy Link Catcher Started            " -ForegroundColor Cyan
Write-Host "  Time: $(Get-Date -UFormat '%Y-%m-%d %H:%M UTC')" -ForegroundColor Yellow
Write-Host "========================================" -ForegroundColor Cyan

# Check for new links every 30 seconds, up to 5 minutes
$StartTime = Get-Date
$EndTime = $StartTime.AddMinutes(5)

while ($CurrentTime -lt $EndTime) {
    Process-QueuedLinks
    Start-Sleep -Seconds 30
}

Write-Host "========================================" -ForegroundColor Cyan
Write-Host "  Link Catcher Cycle Complete           " -ForegroundColor Green
Write-Host "========================================" -ForegroundColor Cyan

# Sumzy - Content Summarizer Utility
# Wraps OpenClaw's summarize skill for analyzing Telegram links

param(
    [Parameter(Mandatory = $true)]
    [string]$url,

    [int]$MaxLength = 5000,  # Max characters to process

    [switch]$Verbose
)

# Paths
$SummarizeScript = Join-Path "D:\AI_PROJECTS\projects\sumzy" "utils\content-summarizer.py"
$CacheDir = "D:\AI_PROJECTS\projects\sumzy\cache"

# Ensure cache directory exists
if (-not (Test-Path $CacheDir)) {
    New-Item -ItemType Directory -Force -Path $CacheDir
}

function Get-Summary {
    param(
        [string]$url,
        [int]$MaxLength = 5000
    )

    # Validate URL
    if ([string]::IsNullOrEmpty($url)) {
        Write-Host "  ❌ Empty URL provided" -ForegroundColor Red
        return $null
    }

    # Check cache first (30min TTL for summaries)
    $CacheFile = Join-Path $CacheDir "${url}.json"
    if (Test-Path $CacheFile) {
        $CachedData = Get-Content $CacheFile -Raw | ConvertFrom-Json
        $LastChecked = [datetime]::Parse($CachedData.lastChecked)

        # Check if cache is still valid (30 minutes TTL)
        if ((Get-Date) -lt ($LastChecked.AddMinutes(30))) {
            Write-Host "  ♻️ Using cached summary" -ForegroundColor Green
            return $CachedData.summary
        }
    }

    # Use summarize skill via OpenClaw API
    try {
        # Method 1: Call the Python summarizer script (preferred)
        if (Test-Path $SummarizeScript) {
            Write-Host "  🔍 Calling content-summarizer.py..." -ForegroundColor Cyan

            # Run the Python summarizer with OpenClaw integration
            $Summary = & python $SummarizeScript `n$url -m $MaxLength 2>&1 | Out-String

            if ([string]::IsNullOrEmpty($Summary) -or $Summary -match '❌ Error' -or $Summary -match 'No content found') {
                Write-Host "  ⚠️ Summarizer returned empty or error" -ForegroundColor Yellow
                return $null
            }

            # Clean up the output (remove markdown formatting)
            $Summary = $Summary -replace '^\s+|-\s+', ''
            $Summary = $Summary -replace '```', ''
            $Summary = $Summary -replace '\.\.\.', '[...]'

            Write-Host "  ✅ Got summary ($($Summary.Length) chars)" -ForegroundColor Green
            return $Summary.Trim()
        }
    } catch {
        Write-Host "  ❌ Error calling summarizer: $_" -ForegroundColor Red
        if ($Verbose) { $_ | Format-List }
        return $null
    }
}

function Save-Cache {
    param(
        [string]$url,
        [string]$summary,
        [double]$timestamp = (Get-Date)
    )

    $CacheData = @{
        url = $url
        summary = $summary
        lastChecked = $timestamp
        cachedAt = Get-Date -Format 'o'
        ttlMinutes = 30
    }

    $CacheFile = Join-Path $CacheDir "${url}.json"
    $CacheData | ConvertTo-Json -Depth 2 | Set-Content $CacheFile -NoNewline
}

# Main execution
Write-Host "========================================" -ForegroundColor Cyan
Write-Host "  Content Summarizer Started            " -ForegroundColor Cyan
Write-Host "  URL: $url" -ForegroundColor Yellow
Write-Host "========================================" -ForegroundColor Cyan

$Summary = Get-Summary -url $url -MaxLength $MaxLength -Verbose:$Verbose

if ($null -ne $Summary) {
    # Cache the result
    Save-Cache -url $url -summary $Summary

    Write-Host "========================================" -ForegroundColor Cyan
    Write-Host "  Summary Retrieved                     " -ForegroundColor Green
    Write-Host "========================================" -ForegroundColor Cyan

    # Output summary to stdout for piping
    if ($Verbose) {
        Write-Host $Summary
    }
} else {
    Write-Host "========================================" -ForegroundColor Cyan
    Write-Host "  ❌ No Summary Available               " -ForegroundColor Red
    Write-Host "========================================" -ForegroundColor Cyan
}

return $Summary
